def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_State_Rankings_Identity_Theft_Reports.csv'
    # Try common encodings for CSVs from PDFs/Excel exports
    for enc in ['utf-8', 'utf-8-sig', 'cp1252', 'latin1']:
        try:
            df = pd.read_csv(path, encoding=enc)
            df['_encoding_used'] = enc
            return pd.concat([df.head(3), df.tail(3)], ignore_index=True)
        except UnicodeDecodeError:
            continue
    # Fallback: replace undecodable bytes
    df = pd.read_csv(path, encoding='utf-8', encoding_errors='replace')
    df['_encoding_used'] = 'utf-8-replace'
    return pd.concat([df.head(3), df.tail(3)], ignore_index=True)

def load() -> pd.DataFrame:
    import pandas as pd
    import pathlib
    path = pathlib.Path('data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_State_Rankings_Fraud_and_Other_Reports.csv')
    # try common encodings
    encodings = ['utf-8', 'cp1252', 'latin1']
    last_err = None
    for enc in encodings:
        try:
            df = pd.read_csv(path, encoding=enc, header=None)
            df['_encoding_used'] = enc
            return pd.concat([df.head(3), df.tail(3)], ignore_index=True)
        except Exception as e:
            last_err = e
    raise last_err
